    fn submit_kernel(
        &mut self,
        device: DeviceId,
        kind: KernelKind,
        reads: &[KernelBuf],
        writes: &[KernelBuf],
        stream: StreamId,
        cooperative: bool,
    ) -> Result<OpId, SimError> {
        let reads = self.resolve_bufs(reads)?;
        let writes = self.resolve_bufs(writes)?;
        self.submit(
            device,
            stream,
            Kind::Kernel {
                kind,
                reads,
                writes,
                cooperative,
            },
        )
    }

