    fn memset_elements_async(
        &mut self,
        device: DeviceId,
        alloc: AllocId,
        count: u64,
        element_size: u32,
        stream: StreamId,
    ) -> Result<OpId, SimError> {
        let bytes = count
            .checked_mul(u64::from(element_size))
            .ok_or(SimError::Invalid {
                why: "memset count",
            })?;
        if bytes == 0 {
            return Err(SimError::Invalid {
                why: "zero-byte memset",
            });
        }
        self.memset_op(
            device,
            MemsetOp {
                id: alloc,
                bytes,
                element_size,
                ..MemsetOp::default()
            },
            stream,
        )
    }

    fn memset_elements_sync(
        &mut self,
        device: DeviceId,
        alloc: AllocId,
        count: u64,
        element_size: u32,
        stream: StreamId,
    ) -> Result<OpId, SimError> {
        if self.capturing.is_some() {
            return Err(SimError::Invalid {
                why: "cannot capture host-sync memset",
            });
        }
        let id = self.memset_elements_async(device, alloc, count, element_size, stream)?;
        self.synchronize_stream(device, stream)?;
        Ok(id)
    }

